PRAGMA foreign_keys = ON;

DROP TABLE IF EXISTS movies;
DROP TABLE IF EXISTS ratings;
DROP TABLE IF EXISTS tags;
DROP TABLE IF EXISTS users;

CREATE TABLE occupations (
    id INTEGER PRIMARY KEY,
    occupation TEXT UNIQUE
);

CREATE TABLE genres (
    id INTEGER PRIMARY KEY,
    genre TEXT NOT NULL UNIQUE
);

CREATE TABLE users (
    id INTEGER PRIMARY KEY,
    first_name TEXT NOT NULL,
    second_name TEXT,
    email TEXT NOT NULL UNIQUE,
    gender TEXT CHECK(gender IN ('male', 'female')),
    register_date DATETIME DEFAULT CURRENT_TIMESTAMP,
    occupationId INTEGER,
    FOREIGN KEY (occupationId) REFERENCES occupations(id)
);

CREATE TABLE movies (
    id INTEGER PRIMARY KEY,
    title TEXT NOT NULL,
    year INTEGER,
    date DATETIME DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE ratings (
    id INTEGER PRIMARY KEY,
    userId INTEGER NOT NULL,
    movieId INTEGER NOT NULL,
    rating REAL NOT NULL CHECK(rating >= 0 AND rating <= 5),
    timestamp DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (userId) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY (movieId) REFERENCES movies(id) ON DELETE RESTRICT
);

CREATE TABLE tags (
    id INTEGER PRIMARY KEY,
    userId INTEGER NOT NULL,
    movieId INTEGER NOT NULL,
    tag TEXT NOT NULL,
    timestamp DATETIME DEFAULT CURRENT_TIMESTAMP,
    -- Тут я чуть-чуть сомневаюсь, поскольку в задании нужно удалить только оценки, но по логике так же нужно удалять и теги от пользователя
    FOREIGN KEY (userId) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY (movieId) REFERENCES movies(id)
);

CREATE TABLE movie_genres (
    id INTEGER PRIMARY KEY,
    movieId INTEGER NOT NULL,
    genreId INTEGER NOT NULL,
    UNIQUE (movieId, genreId),
    FOREIGN KEY (movieId) REFERENCES movies(id),
    FOREIGN KEY (genreId) REFERENCES genres(id)
);

CREATE INDEX idx_users_second_name ON users(second_name);
CREATE INDEX idx_movies_title ON movies(title);
CREATE INDEX idx_movies_year ON movies(year);

BEGIN TRANSACTION;
COMMIT;
